/**
 * Nodo n8n: "0. Sweep renders vencidos (timeout)"
 * Tipo: Code (JavaScript, "Run Once for All Items")
 *
 * Red de seguridad del patrón async: si renderService se cae a mitad de
 * un render (o nunca llega a llamar al webhook de resultado por lo que
 * sea), esto evita que el video quede "colgado" en rendering para
 * siempre. Corre en cada ciclo del Schedule Trigger, en paralelo a la
 * rama que dispara renders nuevos.
 *
 * Env vars usadas: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */
const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_HEADERS = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
  'Content-Type': 'application/json',
};

const TIMEOUT_MINUTES = 10;
const MAX_RENDER_ATTEMPTS = 3;
const cutoff = new Date(Date.now() - TIMEOUT_MINUTES * 60 * 1000).toISOString();

const stuck = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SUPABASE_URL}/rest/v1/renders?status=in.(queued,rendering)&created_at=lt.${encodeURIComponent(cutoff)}&select=id,raw_video_id,attempt,created_at`,
  headers: SUPABASE_HEADERS,
  json: true,
});

const results = [];

for (const render of stuck) {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/renders?id=eq.${render.id}`,
    headers: SUPABASE_HEADERS,
    body: {
      status: 'failed',
      error_message: `Timeout: sin respuesta de render service después de ${TIMEOUT_MINUTES} minutos`,
      stage: 'render',
      updated_at: new Date().toISOString(),
    },
    json: true,
  });

  const nextStatus = render.attempt < MAX_RENDER_ATTEMPTS ? 'edit_spec_ready' : 'failed_render_timeout';

  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/raw_videos?id=eq.${render.raw_video_id}`,
    headers: SUPABASE_HEADERS,
    body: { status: nextStatus },
    json: true,
  });

  results.push({ render_id: render.id, raw_video_id: render.raw_video_id, next_status: nextStatus });
}

return results.map((r) => ({ json: r }));

/**
 * Nodo n8n: "2. Traer edit_spec listo para renderizar"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 *
 * Env vars usadas: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */
const rawVideo = $json;

const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_HEADERS = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
};

const rows = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SUPABASE_URL}/rest/v1/edit_specs?raw_video_id=eq.${rawVideo.id}&status=eq.ready&order=version.desc&limit=1&select=id,spec_json`,
  headers: SUPABASE_HEADERS,
  json: true,
});

const editSpec = rows[0];
if (!editSpec) {
  throw new Error(`raw_video ${rawVideo.id} está en edit_spec_ready pero no se encontró un edit_specs.status='ready' -- revisar Capa 3.`);
}

return [{
  json: {
    raw_video: rawVideo,
    edit_spec_id: editSpec.id,
    spec_json: editSpec.spec_json,
  },
}];

/**
 * Nodo n8n: "3-4. Disparar render en render service y actualizar estado"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 *
 * Llama a POST /render (patrón async: renderService responde de inmediato
 * con un `outcome`, ver comentario en renderService.ts). Este nodo nunca
 * espera a que termine el render -- el resultado real llega después por
 * el webhook "Recibir resultado de render".
 *
 * Env vars usadas: RENDER_SERVICE_URL, SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */
const RENDER_SERVICE_URL = $env.RENDER_SERVICE_URL;
const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_HEADERS = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
  'Content-Type': 'application/json',
};

const MAX_ATTEMPTS = 3;
const currentAttempts = $json.raw_video.render_attempts || 0;

const updateRawVideo = async (fields) => {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/raw_videos?id=eq.${$json.raw_video.id}`,
    headers: SUPABASE_HEADERS,
    body: fields,
    json: true,
  });
};

let response;
try {
  response = await this.helpers.httpRequest({
    method: 'POST',
    url: `${RENDER_SERVICE_URL}/render`,
    body: { edit_spec_id: $json.edit_spec_id },
    json: true,
  });
} catch (err) {
  // render service caído / no accesible por red -- reintento acotado.
  const nextAttempts = currentAttempts + 1;
  await updateRawVideo({
    render_attempts: nextAttempts,
    status: nextAttempts >= MAX_ATTEMPTS ? 'failed_render_dispatch' : 'edit_spec_ready',
  });
  return [{ json: { ...$json, dispatch_ok: false, outcome: 'render_service_unreachable', error: String(err) } }];
}

if (response.outcome === 'queued' || response.outcome === 'already_in_progress') {
  await updateRawVideo({ status: 'rendering', render_attempts: 0 });
  return [{ json: { ...$json, dispatch_ok: true, outcome: response.outcome, render_id: response.render_id } }];
}

if (response.outcome === 'already_done') {
  // Idempotencia real: si ya estaba renderizado, saltamos directo al
  // estado final sin pasar por 'rendering' ni esperar ningún webhook.
  await updateRawVideo({ status: 'rendered_pending_review' });
  return [{
    json: {
      ...$json,
      dispatch_ok: true,
      outcome: 'already_done',
      render_id: response.render_id,
      public_url: response.public_url,
    },
  }];
}

if (response.outcome === 'invalid_edit_spec') {
  // No tiene sentido reintentar solo -- hace falta que Capa 3 regenere el edit_spec.
  await updateRawVideo({ status: 'failed_render_validation', render_attempts: currentAttempts + 1 });
  return [{ json: { ...$json, dispatch_ok: false, outcome: 'invalid_edit_spec', errors: response.errors } }];
}

// not_found, internal_error, missing_input: casos inesperados -- se tratan
// igual que un fallo transitorio, con reintento acotado.
const nextAttempts = currentAttempts + 1;
await updateRawVideo({
  render_attempts: nextAttempts,
  status: nextAttempts >= MAX_ATTEMPTS ? 'failed_render_dispatch' : 'edit_spec_ready',
});
return [{ json: { ...$json, dispatch_ok: false, outcome: response.outcome, error: response.message } }];

/**
 * Nodo n8n: "5. Procesar resultado de render"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 * Disparado por el Webhook "Recibir resultado de render", que recibe el
 * POST que hace renderService cuando termina (bien o mal) un render.
 *
 * Deja preparado el texto y los botones inline de Telegram para el
 * siguiente nodo -- éxito y fallo comparten un único mensaje de salida
 * con distinto contenido, para no necesitar un IF en este tramo.
 *
 * Env vars usadas: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */
// El nodo Webhook de n8n entrega el body del POST bajo $json.body en la
// mayoría de las versiones/configuraciones; esta línea cubre también el
// caso en que tu instancia lo entrega ya aplanado en $json directamente.
const payload = $json.body || $json;

const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_HEADERS = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
  'Content-Type': 'application/json',
};

let text;
let replyMarkup;

if (payload.status === 'done') {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/raw_videos?id=eq.${payload.raw_video_id}`,
    headers: SUPABASE_HEADERS,
    body: { status: 'rendered_pending_review' },
    json: true,
  });

  text = [
    `🎬 Render listo -- ${payload.video_id}`,
    `Tiempo de render: ${Number(payload.render_time_sec).toFixed(1)}s`,
    '',
    `Ver video: ${payload.public_url}`,
    '',
    '¿Qué hacemos con este video?',
  ].join('\n');

  replyMarkup = {
    inline_keyboard: [[
      { text: '✅ Aprobar', callback_data: `appr:${payload.render_id}` },
      { text: '❌ Rechazar', callback_data: `rejt:${payload.render_id}` },
      { text: '🔁 Pedir variante', callback_data: `varr:${payload.render_id}` },
    ]],
  };
} else {
  const failedStatus = payload.stage === 'upload' ? 'failed_upload' : 'failed_render';

  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/raw_videos?id=eq.${payload.raw_video_id}`,
    headers: SUPABASE_HEADERS,
    body: { status: failedStatus },
    json: true,
  });

  text = [
    `❌ Falló el render -- raw_video ${payload.raw_video_id}`,
    `Etapa: ${payload.stage === 'upload' ? 'subida a Storage' : 'render con Remotion'}`,
    `Error: ${payload.error}`,
  ].join('\n');

  replyMarkup = {
    inline_keyboard: [[
      { text: '🔁 Reintentar', callback_data: `retr:${payload.raw_video_id}` },
    ]],
  };
}

return [{
  json: {
    ...payload,
    telegram_text: text,
    telegram_reply_markup: JSON.stringify(replyMarkup),
  },
}];

/**
 * Nodo n8n: "6. Procesar decisión de revisión"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 * Disparado por el Telegram Trigger, escuchando actualizaciones tipo
 * callback_query (los clicks en los botones del mensaje de revisión).
 *
 * callback_data llega en el formato "<accion>:<id>":
 *   appr = aprobar          (id = render_id)
 *   rejt = rechazar         (id = render_id)
 *   varr = pedir variante   (id = render_id)
 *   retr = reintentar render (id = raw_video_id)
 *
 * Esto es la versión mínima de Capa 5 (revisión humana) -- deja escrito
 * en review_actions y raw_videos.status lo necesario para que la Capa 5
 * "de verdad" (portal propio, ver sistema-fabrica-reels-nexoia.md sección
 * 14) se enchufe después sin cambiar el modelo de datos.
 *
 * Env vars usadas: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */
const update = $json;
const callbackQuery = update.callback_query;

if (!callbackQuery) {
  // Update de Telegram que no es un click de botón (ej. un mensaje de
  // texto normal al bot) -- no hacemos nada con esto en este flujo.
  return [{ json: { skip: true } }];
}

const [action, targetId] = (callbackQuery.data || '').split(':');
const reviewer = callbackQuery.from && callbackQuery.from.username
  ? `telegram:@${callbackQuery.from.username}`
  : `telegram:${callbackQuery.from ? callbackQuery.from.id : 'desconocido'}`;

const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_HEADERS = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
  'Content-Type': 'application/json',
  Prefer: 'return=representation',
};

const getRender = async (renderId) => {
  const rows = await this.helpers.httpRequest({
    method: 'GET',
    url: `${SUPABASE_URL}/rest/v1/renders?id=eq.${renderId}&select=id,raw_video_id`,
    headers: SUPABASE_HEADERS,
    json: true,
  });
  return rows[0];
};

let confirmationText = '';
let toastText = '';

if (action === 'appr' || action === 'rejt' || action === 'varr') {
  const render = await getRender(targetId);
  if (!render) {
    return [{ json: { skip: true, error: `render ${targetId} no encontrado` } }];
  }

  const decisionMap = { appr: 'approved', rejt: 'rejected', varr: 'variant_requested' };
  const decision = decisionMap[action];

  await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/review_actions`,
    headers: SUPABASE_HEADERS,
    body: { render_id: targetId, reviewer, decision, decided_at: new Date().toISOString() },
    json: true,
  });

  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/raw_videos?id=eq.${render.raw_video_id}`,
    headers: SUPABASE_HEADERS,
    body: { status: decision },
    json: true,
  });

  const labelMap = { appr: '✅ Aprobado', rejt: '❌ Rechazado', varr: '🔁 Variante solicitada' };
  confirmationText = `${labelMap[action]} por ${reviewer}`;
  toastText = labelMap[action];
} else if (action === 'retr') {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/raw_videos?id=eq.${targetId}`,
    headers: SUPABASE_HEADERS,
    body: { status: 'edit_spec_ready', render_attempts: 0 },
    json: true,
  });
  confirmationText = `🔁 Reintento encolado por ${reviewer} -- se vuelve a disparar en el próximo ciclo (cada 2 min).`;
  toastText = 'Reintento encolado';
} else {
  return [{ json: { skip: true, error: `acción desconocida: ${action}` } }];
}

return [{
  json: {
    skip: false,
    callback_query_id: callbackQuery.id,
    chat_id: callbackQuery.message && callbackQuery.message.chat ? callbackQuery.message.chat.id : null,
    message_id: callbackQuery.message ? callbackQuery.message.message_id : null,
    confirmation_text: confirmationText,
    toast_text: toastText,
  },
}];
